export function defineAsyncView(loader) {
  let pendingRequest = null;
  let resolvedView;
  const load = () => {
    let thisRequest;
    return pendingRequest || (thisRequest = pendingRequest = loader()
      .catch(error => { throw error instanceof Error ? error : new Error(String(error)); })
      .then(view => {
        if (thisRequest !== pendingRequest && pendingRequest) return pendingRequest;
        resolvedView = view;
        return view;
      }));
  };
  return {
    setup(instance) {
      if (resolvedView) return () => resolvedView;
      const loaded = { value: false };
      const onError = error => {
        pendingRequest = null;
        instance.onError(error);
      };
      load().then(() => {
        loaded.value = true;
      }).catch(error => {
        onError(error);
      });
      return () => loaded.value && resolvedView ? resolvedView : null;
    },
  };
}

